solution:
def is_tuple_visible(tuple_hdr: dict, snapshot: dict, committed_txns: set[int]) -> bool:
    xmin = tuple_hdr["xmin"]
    xmax = tuple_hdr.get("xmax")
    snap_xmin = snapshot["xmin"]
    snap_xmax = snapshot["xmax"]
    active = set(snapshot.get("active_txns", []))

    # 1. Creator (xmin) check
    if xmin >= snap_xmax:
        return False
    if xmin in active:
        return False
    if xmin not in committed_txns:
        return False

    # 2. Deleter (xmax) check
    if xmax is None:
        return True
    if xmax >= snap_xmax:
        return True
    if xmax in active:
        return True
    if xmax not in committed_txns:
        return True

    # xmax committed before snapshot -> deleted and invisible
    return False

tests.code:
snap = {"xmin": 100, "xmax": 110, "active_txns": [102, 105]}
committed = {90, 95, 99}
tup = {"xmin": 95, "xmax": None}
assert is_tuple_visible(tup, snap, committed) is True

snap = {"xmin": 100, "xmax": 110, "active_txns": [102, 105]}
committed = {90, 102}
tup = {"xmin": 102, "xmax": None}
assert is_tuple_visible(tup, snap, committed) is False

snap = {"xmin": 100, "xmax": 110, "active_txns": []}
committed = {90, 115}
tup = {"xmin": 90, "xmax": 115}  # deleted by txn 115 (future)
assert is_tuple_visible(tup, snap, committed) is True

snap = {"xmin": 100, "xmax": 110, "active_txns": []}
committed = {80, 90}
tup = {"xmin": 80, "xmax": 90}  # deleted by txn 90 (< snapshot.xmin)
assert is_tuple_visible(tup, snap, committed) is False
